import { UsageError } from './nerdgraph.mjs';
import { isMap } from './steps.mjs';
import { truncate } from './text.mjs';
import { INPUT_TYPES, MAX_SCAN_CHARS, VALIDATION_PROPERTY, findToken } from './validation.mjs';

// Regex validations come from the published definition, which anyone with account access can edit, so a pattern like
// ^(a+)+$ could block this process. The test runs in a vm with a time limit (a CPU guard, not a security boundary: the
// script is a fixed string and the pattern and value are only data). One context is reused: a new one per call is slower
// and leaks memory.
const REGEX_TIMEOUT_MS = 100;
const regexScript = new Script('re.test(value)');
